import{_ as e,o,c as a,al as r}from"./chunks/framework.BawR2jEz.js";const g=JSON.parse('{"title":"UI Kit","description":"Конструктор фирменных элементов интерфейса — кнопки, поля форм, бейджи и типографика. Цветовые роли, заливки, рецепты весов, размеры и состояния в одном месте.","frontmatter":{"title":"UI Kit","description":"Конструктор фирменных элементов интерфейса — кнопки, поля форм, бейджи и типографика. Цветовые роли, заливки, рецепты весов, размеры и состояния в одном месте."},"headers":[],"relativePath":"fast-settings/ui-kit/index.md","filePath":"fast-settings/ui-kit/index.md"}'),d={name:"fast-settings/ui-kit/index.md"};function i(s,t,l,n,c,h){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="ui-kit" tabindex="-1">UI Kit <a class="header-anchor" href="#ui-kit" aria-label="Permalink to &quot;UI Kit&quot;">​</a></h1><p>Конструктор фирменных элементов интерфейса. Настраиваете кнопки, поля форм, бейджи и типографику один раз — модуль собирает из этого CSS и подключает его к сайту. Вид меняется сразу везде, шаблоны трогать не нужно.</p><p>Ключевая идея: цвета задаются <strong>ролями</strong>, а не значениями. Кнопка не «оранжевая» — она «акцентная». Поменяли цветовую схему проекта, и акцентными стали все кнопки, бейджи и ссылки разом.</p><h2 id="включение" tabindex="-1">Включение <a class="header-anchor" href="#включение" aria-label="Permalink to &quot;Включение&quot;">​</a></h2><p>Включение двухуровневое:</p><ol><li><strong>Мастер-тумблер</strong> генератора. Выключен — в CSS не добавляется ничего, ни байта.</li><li><strong>Тумблер элемента</strong>. Каждый из четырёх элементов включается отдельно: можно взять только типографику, а кнопки оставить теме.</li></ol><p>Выключенный элемент не просто скрыт — его стили не генерируются.</p><h2 id="элементы" tabindex="-1">Элементы <a class="header-anchor" href="#элементы" aria-label="Permalink to &quot;Элементы&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Элемент</th><th>Что настраивается</th></tr></thead><tbody><tr><td><strong>Кнопки</strong></td><td>Цветовые роли, заливки, размеры, состояния, иконки, форма</td></tr><tr><td><strong>Поля форм</strong></td><td>Размеры, рамки, фон, состояния (наведение, фокус, ошибка, успех, отключено)</td></tr><tr><td><strong>Бейджи</strong></td><td>То же, что у кнопок, но без интерактивных состояний — бейдж статичен</td></tr><tr><td><strong>Типографика</strong></td><td>Заголовки, абзацы, ссылки, списки, цитаты внутри области контента</td></tr></tbody></table><p>Типографика устроена иначе остальных — у неё нет ролей и заливок, зато есть адаптив по брейкпоинтам. Ей посвящена <a href="./typography.html">отдельная страница</a>.</p><h2 id="цветовые-роли" tabindex="-1">Цветовые роли <a class="header-anchor" href="#цветовые-роли" aria-label="Permalink to &quot;Цветовые роли&quot;">​</a></h2><p>Роль — это смысловое имя цвета: <code>accent</code>, <code>primary</code>, <code>success</code>, <code>error</code>. Цвет для роли берётся из одного из трёх источников:</p><ul><li><strong>Роль схемы</strong> — цвет приходит из активной цветовой схемы и переворачивается вместе с тёмной темой автоматически.</li><li><strong>Палитра</strong> — цвет и его оттенки берутся из палитры проекта. Даёт полную шкалу весов.</li><li><strong>Свой цвет</strong> — hex вручную. Оттенки для него вычисляются на лету.</li></ul><p>Встроенные роли покрывают обычные нужды: акцент, три брендовых цвета, нейтральная поверхность и четыре функциональных (успех, предупреждение, ошибка, информация). Своих можно добавить сколько угодно — кнопка <strong>«Добавить вариант»</strong>, ключ в kebab-case.</p><h2 id="заливки" tabindex="-1">Заливки <a class="header-anchor" href="#заливки" aria-label="Permalink to &quot;Заливки&quot;">​</a></h2><p>Один и тот же цвет даёт четыре внешности:</p><table tabindex="0"><thead><tr><th>Заливка</th><th>Как выглядит</th></tr></thead><tbody><tr><td><strong>solid</strong></td><td>Сплошной фон, контрастный текст</td></tr><tr><td><strong>outline</strong></td><td>Прозрачный фон, цветные рамка и текст</td></tr><tr><td><strong>soft</strong></td><td>Мягкий подкрашенный фон, тёмный текст</td></tr><tr><td><strong>ghost</strong></td><td>Ни фона, ни рамки — только цвет текста</td></tr></tbody></table><p>Лишние можно выключить: если в проекте не нужен ghost, он не будет ни в CSS, ни в галерее.</p><p><strong>solid работает без класса.</strong> Элемент без единого класса заливки выглядит как solid — в разметке достаточно <code>btn--exdoc btn--accent</code>. Это соглашение по умолчанию, а не потеря управления: явный класс всегда сильнее.</p><h2 id="рецепты-откуда-берутся-оттенки" tabindex="-1">Рецепты: откуда берутся оттенки <a class="header-anchor" href="#рецепты-откуда-берутся-оттенки" aria-label="Permalink to &quot;Рецепты: откуда берутся оттенки&quot;">​</a></h2><p>Рецепт — таблица, которая говорит, какой <strong>вес</strong> цвета идёт в какой слот. Слоты — фон, текст, граница и их варианты при наведении и нажатии.</p><p>Веса — ступени шкалы от светлого к тёмному: <code>50</code>, <code>100</code>, … <code>500</code>, … <code>900</code>. <code>500</code> — базовый цвет роли. Отдельное значение <code>on</code> означает «контрастный к фону» — текст на сплошной заливке.</p><p>Например, рецепт solid по умолчанию: фон <code>500</code>, текст <code>on</code>, граница <code>500</code>, фон при наведении <code>600</code>. Меняете <code>600</code> на <code>700</code> — все solid-кнопки станут темнее при наведении.</p><p>Рецепт общий для всех ролей, но любую ячейку можно переопределить <strong>для одной роли</strong>: выберите роль в переключателе над таблицей и задайте своё значение. Переопределения хранятся отдельно от общего рецепта, поэтому сбрасываются по одному или все сразу.</p><div class="tip custom-block"><p class="custom-block-title">Схемные роли и тонкая шкала</p><p>У роли, привязанной к схеме, тонкие оттенки схлопываются: веса выше <code>500</code> дают один и тот же «темнее», ниже <code>500</code> — прозрачные тинты базового цвета. Полная шкала работает у палитровых ролей — если нужны тонкие переходы, берите цвет из палитры.</p></div><h2 id="размеры" tabindex="-1">Размеры <a class="header-anchor" href="#размеры" aria-label="Permalink to &quot;Размеры&quot;">​</a></h2><p>Три размера — <code>sm</code>, <code>md</code>, <code>lg</code>, и один из них выбирается размером по умолчанию: элемент без класса размера получает именно его.</p><p>Для каждого настраиваются высота, отступы (общие или отдельно по сторонам), кегль и жирность шрифта, размер иконки и промежуток между иконкой и текстом, радиус скругления (общий или по углам).</p><p>Размеры кнопок и полей форм независимы — совпадать по высоте они не обязаны.</p><h2 id="оформление-и-состояния" tabindex="-1">Оформление и состояния <a class="header-anchor" href="#оформление-и-состояния" aria-label="Permalink to &quot;Оформление и состояния&quot;">​</a></h2><p>Вкладка <strong>«Оформление»</strong> — то, что не зависит от роли: гарнитура, толщина и стиль рамки, регистр текста, межбуквенный интервал, высота строки, тень, переход, кольцо фокуса, прозрачность отключённого состояния.</p><p>У полей форм состояния вынесены отдельно: наведение, фокус, ошибка, успех, отключено — у каждого свои фон, текст и рамка. Ошибка и успех подхватываются как по классам <code>is-invalid</code> / <code>is-valid</code>, так и по нативной валидации браузера.</p><p>Пустое поле означает «не задавать» — в CSS такое свойство не попадёт, и элемент останется с тем, что даёт тема.</p><h2 id="тени" tabindex="-1">Тени <a class="header-anchor" href="#тени" aria-label="Permalink to &quot;Тени&quot;">​</a></h2><p>Тень — не одно значение, а стопка слоёв: у каждого свои смещение, размытие, растяжение, цвет и признак внутренней. Слои можно скрывать по одному, не удаляя, — удобно подбирать. Готовое значение из переменных проекта тоже подойдёт.</p><h2 id="базовыи-класс" tabindex="-1">Базовый класс <a class="header-anchor" href="#базовыи-класс" aria-label="Permalink to &quot;Базовый класс&quot;">​</a></h2><p>Если в теме уже есть родной класс элемента (<code>btn</code>, <code>badge</code>), впишите его в поле <strong>«Базовый класс»</strong>. Базовый блок стилей — геометрия, отступы, шрифт — дополнительно применится и к нему, а цветовые модификаторы останутся на классе exDoc.</p><p>Так вёрстка темы получает фирменные размеры без правки шаблонов.</p><h2 id="свои-scss" tabindex="-1">Свой SCSS <a class="header-anchor" href="#свои-scss" aria-label="Permalink to &quot;Свой SCSS&quot;">​</a></h2><p>Блок для случаев, которые конструктор не покрывает: свои классы-модификаторы, градиенты, нестандартные состояния. Код компилируется вместе с остальными стилями и имеет доступ к переменным проекта.</p><p>Импорты (<code>@import</code>, <code>@use</code>) запрещены, размер ограничен — блок рассчитан на добавку, а не на подключение сторонних библиотек.</p><h2 id="превью" tabindex="-1">Превью <a class="header-anchor" href="#превью" aria-label="Permalink to &quot;Превью&quot;">​</a></h2><p>Три режима просмотра:</p><ul><li><strong>Галерея</strong> — стенд со всеми сочетаниями ролей, заливок, размеров и состояний. Фильтры сверху сужают выборку: только outline, только крупные, только состояние наведения.</li><li><strong>Витрина сайта</strong> — те же элементы, но на реальной странице каталога, в окружении темы.</li><li><strong>Страница сайта</strong> — любая страница вашего сайта с применёнными стилями.</li></ul><p>Над превью — переключатель светлой и тёмной темы и панель вьюпорта: ширина и высота кадра, пресеты устройств, масштаб. Полоса над кадром показывает брейкпоинты проекта; клик по ней ставит соответствующую ширину.</p><h2 id="как-стили-попадают-на-саит" tabindex="-1">Как стили попадают на сайт <a class="header-anchor" href="#как-стили-попадают-на-саит" aria-label="Permalink to &quot;Как стили попадают на сайт&quot;">​</a></h2><p>CSS собирается при сохранении и подключается вместе с остальными стилями проекта. Отдельно ничего компилировать не нужно.</p><p>Пока элемент выключен, его правил в файле нет вовсе — включение и выключение не оставляет мёртвого кода.</p><h2 id="см-также" tabindex="-1">См. также <a class="header-anchor" href="#см-также" aria-label="Permalink to &quot;См. также&quot;">​</a></h2><ul><li><a href="./typography.html">UI Kit — Типографика</a> — стили содержимого: заголовки, абзацы, списки.</li><li><a href="./classes.html">UI Kit — контракт классов</a> — как пользоваться сгенерированными стилями в своей вёрстке.</li><li><a href="./components.html">UI Kit — готовые компоненты</a> — Twig-компоненты под этот контракт.</li><li><a href="./../palettes.html">Палитры</a> — наборы оттенков, из которых берутся цвета.</li><li><a href="./../schemes.html">Схемы</a> — раздача цветов по ролям.</li><li><a href="./../variables.html">Переменные</a> — брейкпоинты, шрифты, тени и другие токены проекта.</li></ul>',50)])])}const u=e(d,[["render",i]]);export{g as __pageData,u as default};
